using System.Text;
using Cthangover.Core.Mods;
using Cthangover.Core.Mods.Pipeline;
using Cthangover.Core.Mods.Providers;

namespace Engine.Tests.Mods
{
    /// <summary>Real 7z fixtures generated by the official tool, shared unchanged by Windows and Linux tests.</summary>
    public class SevenZipModFileProviderTests : IDisposable
    {
        private const string FixturePassword = SevenZipFixtures.Password;
        private readonly string temporary = Path.Combine(Path.GetTempPath(), "sevenzip_" + Guid.NewGuid().ToString("N"));
        private string caseName;
        private string casePassword;
        private string invalidArchivePath;
        private SevenZipModFileProvider disposedProvider;

        public SevenZipModFileProviderTests() => Directory.CreateDirectory(temporary);

        public void Dispose() => Directory.Delete(temporary, true);

        [Theory]
        [InlineData("plain", null)]
        [InlineData("solid", null)]
        [InlineData("encrypted", FixturePassword)]
        [InlineData("encrypted_solid", FixturePassword)]
        [InlineData("encrypted_headers", FixturePassword)]
        [InlineData("encrypted_headers_solid", FixturePassword)]
        public void ReadsManifestTextBinaryAndListings(string name, string password)
        {
            using var provider = new SevenZipModFileProvider(SevenZipFixtures.PathFor(name), "test_sevenzip", password);
            Assert.Equal(Path.GetFullPath(SevenZipFixtures.PathFor(name)), provider.RootPath);
            Assert.Equal("test_sevenzip", provider.Mod);
            Assert.Equal("test_sevenzip", ModDiscoveryService.ReadManifest(provider, out var problem).Id);
            Assert.Null(problem);
            Assert.Equal("Привет из 7z!\n", provider.ReadFileText("Data/привет.txt"));
            Assert.Equal("Привет из 7z!\n", provider.ReadFileText("Data\\привет.txt"));
            Assert.Equal(SevenZipFixtures.Payload(), provider.ReadFileBinary("Data/payload.bin"));
            Assert.Empty(provider.ReadFileBinary("zero.txt"));
            var rootFiles = provider.ListFiles().ToArray();
            var dataFiles = provider.ListFiles("Data").ToArray();
            Array.Sort(rootFiles, StringComparer.Ordinal);
            Array.Sort(dataFiles, StringComparer.Ordinal);
            Assert.Equal(new[] { "Data/", "empty/", "manifest.json", "zero.txt" }, rootFiles);
            Assert.Equal(new[] { "Data/payload.bin", "Data/привет.txt" }, dataFiles);
            Assert.False(provider.FileExists("data/payload.bin"));
            Assert.False(provider.FileExists("Data"));
            Assert.Null(provider.OpenStream("missing.txt"));
            Assert.Null(provider.ReadFileBinary("missing.txt"));
            Assert.Null(provider.ReadFileText("missing.txt"));
            Assert.Null(provider.GetFileSystemPath("manifest.json"));
            Assert.Equal("manifest.json", provider.ResolveIncludePath("../manifest.json", "Data/привет.txt"));
        }

        [Theory]
        [InlineData("encrypted", null)]
        [InlineData("encrypted", "wrong")]
        [InlineData("encrypted_solid", null)]
        [InlineData("encrypted_solid", "wrong")]
        [InlineData("encrypted_headers", null)]
        [InlineData("encrypted_headers", "wrong")]
        [InlineData("encrypted_headers_solid", null)]
        [InlineData("encrypted_headers_solid", "wrong")]
        public void MissingOrIncorrectPasswordCannotReadContent(string name, string password)
        {
            caseName = name;
            casePassword = password;
            Assert.ThrowsAny<Exception>(ReadEncryptedPayload);
        }

        [Theory]
        [InlineData("solid", null)]
        [InlineData("encrypted_headers_solid", FixturePassword)]
        public async Task PartialInterleavedAndConcurrentStreamsRemainIndependent(string name, string password)
        {
            using var provider = new SevenZipModFileProvider(SevenZipFixtures.PathFor(name), "test", password);
            using (var partial = provider.OpenStream("Data/payload.bin"))
            {
                Assert.Equal(0, partial.ReadByte());
                Assert.Equal("Привет из 7z!\n", provider.ReadFileText("Data/привет.txt"));
                Assert.Equal(1, partial.ReadByte());
            }
            var tasks = new Task<byte[]>[4];
            for (var index = 0; index < tasks.Length; index++)
                tasks[index] = Task.Factory.StartNew(ReadConcurrentPayload, provider,
                    CancellationToken.None, TaskCreationOptions.DenyChildAttach, TaskScheduler.Default);
            var reads = await Task.WhenAll(tasks);
            var expected = SevenZipFixtures.Payload();
            foreach (var data in reads)
                Assert.Equal(expected, data);
            Assert.Equal("Привет из 7z!\n", provider.ReadFileText("Data/привет.txt"));
        }

        [Fact]
        public void DisposeReleasesFilesAndPreventsNewReads()
        {
            var path = Path.Combine(temporary, "copy.7z");
            File.Copy(SevenZipFixtures.PathFor("encrypted_headers_solid"), path);
            var provider = new SevenZipModFileProvider(path, "test", FixturePassword);
            using (var stream = provider.OpenStream("Data/payload.bin"))
                Assert.Equal(0, stream.ReadByte());
            provider.Dispose();
            provider.Dispose();
            disposedProvider = provider;
            Assert.Throws<ObjectDisposedException>(OpenDisposedProvider);
            File.Move(path, path + ".moved");
            Assert.True(File.Exists(path + ".moved"));
        }

        [Fact]
        public void InvalidArchiveIsRejected()
        {
            invalidArchivePath = Path.Combine(temporary, "broken.7z");
            File.WriteAllText(invalidArchivePath, "not an archive", Encoding.UTF8);
            Assert.ThrowsAny<Exception>(OpenInvalidArchive);
            File.Delete(invalidArchivePath);
        }

        private void ReadEncryptedPayload()
        {
            using var provider = new SevenZipModFileProvider(SevenZipFixtures.PathFor(caseName), "test", casePassword);
            provider.ReadFileBinary("Data/payload.bin");
        }

        private static byte[] ReadConcurrentPayload(object state) =>
            ((SevenZipModFileProvider)state).ReadFileBinary("Data/payload.bin");

        private void OpenDisposedProvider()
        {
            using var stream = disposedProvider.OpenStream("manifest.json");
        }

        private void OpenInvalidArchive()
        {
            using var provider = new SevenZipModFileProvider(invalidArchivePath, "test");
        }
    }
}
